package com.nigson.commerce.order;

import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.commerce.inventory.*;
import com.nigson.commerce.pricing.*;
import com.nigson.commerce.payment.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
import com.nigson.shared.events.EventCodec;

/** Order-first local workflow: a request reserves quantities, receipt proves goods, Finance owns money. */
public final class ReturnService {
 private final JdbcTemplate jdbc;private final OrderAuthority orders;private final InventoryAuthority operations;private final PricingAuthority finance;
 private final StockLedger stock;private final PaymentRepository refunds;private final PaymentPolicy paymentPolicy;private final OrderPolicy binding;
 private final PlatformStore commands;private final AuditWriter audit;private final Clock clock;private final TransactionTemplate reads;
 public ReturnService(JdbcTemplate jdbc,PlatformTransactionManager manager,OrderAuthority orders,InventoryAuthority operations,PricingAuthority finance,StockLedger stock,PaymentRepository refunds,PaymentPolicy paymentPolicy,OrderPolicy binding,PlatformStore commands,AuditWriter audit,Clock clock){this.jdbc=jdbc;this.orders=orders;this.operations=operations;this.finance=finance;this.stock=stock;this.refunds=refunds;this.paymentPolicy=paymentPolicy;this.binding=binding;this.commands=commands;this.audit=audit;this.clock=clock;reads=new TransactionTemplate(manager);reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);reads.setTimeout(3);}
 private java.sql.Timestamp stamp(){return java.sql.Timestamp.from(clock.instant());}
 private void limits(){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");}
 private Map<String,Object> order(UUID id,boolean lock){var rows=jdbc.queryForList("SELECT * FROM commerce.sales_order WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 private UUID owner(UUID id){var rows=jdbc.query("SELECT order_id FROM commerce.return_request WHERE id=?",(r,n)->r.getObject(1,UUID.class),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 private Map<String,Object> request(UUID id){var rows=jdbc.queryForList("SELECT * FROM commerce.return_request WHERE id=? FOR UPDATE",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 private void version(Map<String,Object> row,long expected){if(((Number)row.get("version")).longValue()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(expected==Long.MAX_VALUE)throw OrderValues.rule();}
 private boolean delivered(Map<String,Object> o){return Set.of("DELIVERED","REFUNDED").contains(o.get("status"))&&"DELIVERED".equals(o.get("fulfillment_status"));}
 private BigDecimal delivered(UUID order,UUID line){BigDecimal shipped=jdbc.queryForObject("SELECT coalesce(sum(l.quantity),0) FROM commerce.shipment_line l JOIN commerce.shipment s ON s.id=l.shipment_id WHERE s.order_id=? AND l.order_line_id=? AND s.status='DELIVERED' AND s.dispatched_at IS NOT NULL AND s.delivered_at IS NOT NULL AND s.delivered_at<=?",BigDecimal.class,order,line,stamp());BigDecimal debited=jdbc.queryForObject("SELECT coalesce(-sum(delta_on_hand),0) FROM commerce.inventory_movement WHERE order_id=? AND order_line_id=? AND movement_type='DISPATCH'",BigDecimal.class,order,line);return shipped.min(debited);}
 private BigDecimal available(UUID order,UUID line){BigDecimal claimed=jdbc.queryForObject("SELECT coalesce(sum(quantity),0) FROM commerce.return_request WHERE order_id=? AND order_line_id=? AND state<>'REJECTED'",BigDecimal.class,order,line);BigDecimal restocked=jdbc.queryForObject("SELECT coalesce(sum(quantity),0) FROM commerce.return_request WHERE order_id=? AND order_line_id=? AND state='RECEIVED' AND restock",BigDecimal.class,order,line);BigDecimal physical=jdbc.queryForObject("SELECT coalesce(sum(delta_on_hand),0) FROM commerce.inventory_movement WHERE order_id=? AND order_line_id=? AND movement_type='RETURN' AND return_kind='PHYSICAL_RETURN'",BigDecimal.class,order,line);return delivered(order,line).subtract(claimed).subtract(physical.subtract(restocked).max(BigDecimal.ZERO));}
 private BigDecimal refundable(UUID id){return jdbc.queryForObject("SELECT greatest(o.grand_total-coalesce((SELECT sum(r.amount) FROM commerce.refund r WHERE r.order_id=o.id AND r.state NOT IN ('FAILED','REJECTED')),0),0) FROM commerce.sales_order o WHERE o.id=?",BigDecimal.class,id);}
 private boolean verified(UUID order){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.sales_order o JOIN commerce.payment_attempt a ON a.order_id=o.id JOIN commerce.payment_transaction t ON t.attempt_id=a.id WHERE o.id=? AND a.provider='PAYSTACK' AND a.merchant_account=? AND a.provider_mode=? AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL AND a.expected_amount=o.grand_total AND t.settled_amount=a.expected_amount AND a.currency_code=o.currency_code AND t.currency_code=a.currency_code AND t.provider_mode=a.provider_mode AND t.provider_status='success')",Boolean.class,order,binding.merchantAccount(),binding.mode()));}
 private ReturnValues.Item item(UUID id){var rows=jdbc.query("SELECT r.*,l.product_name,f.state AS refund_state FROM commerce.return_request r JOIN commerce.order_line l ON l.id=r.order_line_id LEFT JOIN commerce.refund f ON f.id=r.refund_id WHERE r.id=?",(r,n)->new ReturnValues.Item(id,r.getObject("order_id",UUID.class),r.getObject("order_line_id",UUID.class),r.getString("product_name"),PricingValues.decimal(r.getBigDecimal("quantity")),r.getString("reason"),r.getString("policy_revision"),r.getString("state"),r.getString("decision_reason"),r.getString("instructions"),r.getString("receipt_reference"),(Boolean)r.getObject("restock"),r.getTimestamp("received_at")==null?null:r.getTimestamp("received_at").toInstant(),r.getObject("refund_id",UUID.class),r.getString("refund_state"),r.getLong("version"),r.getTimestamp("created_at").toInstant()),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 public ReturnValues.View get(ActorAssertion.Actor actor,UUID id,boolean staff){if(staff)orders.staff(actor,false,false);else orders.owned(actor,id,false);return reads.execute(status->{limits();if(staff)orders.staff(actor,false,false);else orders.owned(actor,id,false);var o=order(id,false);boolean eligible=delivered(o);var lines=jdbc.queryForList("SELECT l.id,l.product_name,l.quantity,s.quantity_scale FROM commerce.order_line l JOIN commerce.sku s ON s.id=l.sku_id WHERE l.order_id=? ORDER BY l.id LIMIT 101",id);if(lines.size()>100)throw OrderValues.rule();var choices=new ArrayList<ReturnValues.Line>();for(var line:lines){UUID key=(UUID)line.get("id");choices.add(new ReturnValues.Line(key,line.get("product_name").toString(),PricingValues.decimal((BigDecimal)line.get("quantity")),PricingValues.decimal(eligible?available(id,key).max(BigDecimal.ZERO):BigDecimal.ZERO),((Number)line.get("quantity_scale")).intValue()));}var ids=jdbc.query("SELECT id FROM commerce.return_request WHERE order_id=? ORDER BY created_at DESC,id DESC LIMIT 101",(r,n)->r.getObject(1,UUID.class),id);if(ids.size()>100)throw OrderValues.rule();return new ReturnValues.View(id,((Number)o.get("version")).longValue(),eligible,List.copyOf(choices),ids.stream().map(this::item).toList(),PaymentValues.money(refundable(id).toPlainString(),false),verified(id)&&refundable(id).signum()>0);});}
 private PlatformStore.Response execute(ActorAssertion.Actor actor,String api,String key,Object body,UUID correlation,Runnable authority,java.util.function.Supplier<PlatformStore.Response> mutation){ApiValues.idempotencyKey(key);ApiValues.uuid(correlation==null?null:correlation.toString());authority.run();try{return commands.executeLocal(actor.party().toString(),api,key,EventCodec.JSON.valueToTree(body),db->{limits();authority.run();return mutation.get();});}catch(org.springframework.dao.DataAccessException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failure;}}
 private void touch(UUID order,String actor){jdbc.update("UPDATE commerce.sales_order SET version=version+1,updated_at=?,updated_by=? WHERE id=?",stamp(),actor,order);}
 private void evidence(ActorAssertion.Actor actor,UUID id,UUID correlation,AuditValues.Action action,String state){audit.append(actor.party().toString(),AuditValues.ActorKind.USER,action,AuditValues.Resource.RETURN_REQUEST,id,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("state",state),null);}
 private ReturnValues.Item current(ActorAssertion.Actor actor,UUID id,boolean staff){if(staff)orders.staff(actor,false,false);else orders.owned(actor,owner(id),false);return reads.execute(s->item(id));}
 public ReturnValues.Item create(ActorAssertion.Actor actor,UUID order,long expected,ReturnValues.Request input,String key,UUID correlation){orders.owned(actor,order,false);var result=execute(actor,"API-238",key,Map.of("order",order,"version",expected,"input",input),correlation,()->orders.owned(actor,order,true),()->{var o=order(order,true);version(o,expected);if(!delivered(o))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);var lines=jdbc.queryForList("SELECT s.quantity_scale FROM commerce.order_line l JOIN commerce.sku s ON s.id=l.sku_id WHERE l.id=? AND l.order_id=?",input.orderLineId(),order);if(lines.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);BigDecimal quantity=PricingValues.quantity(input.quantity(),((Number)lines.getFirst().get("quantity_scale")).intValue());if(quantity.compareTo(available(order,input.orderLineId()))>0)throw OrderValues.rule();if(jdbc.queryForObject("SELECT count(*) FROM commerce.return_request WHERE order_id=?",Integer.class,order)>=100)throw OrderValues.rule();String policy=EventCodec.JSON.readTree(o.get("commercial_snapshot").toString()).path("returnsPolicyRevision").asString();if(policy.isBlank()||policy.length()>80)throw OrderValues.rule();UUID id=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO commerce.return_request(id,created_by,updated_by,order_id,order_line_id,requested_by,quantity,reason,policy_revision) VALUES (?,?,?,?,?,?,?,?,?)",id,actor.party().toString(),actor.party().toString(),order,input.orderLineId(),actor.party(),quantity,input.reason(),policy);touch(order,actor.party().toString());evidence(actor,id,correlation,AuditValues.Action.RETURN_REQUEST,"REQUESTED");return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(Map.of("id",id)),id);});return current(actor,result.resource(),false);}
 public ReturnValues.Item review(ActorAssertion.Actor actor,UUID id,long expected,ReturnValues.Review input,String key,UUID correlation){operations.require(actor);UUID order=owner(id);var result=execute(actor,"API-240",key,Map.of("id",id,"version",expected,"input",input),correlation,()->{operations.require(actor);},()->{operations.stabilize(actor);order(order,true);var before=request(id);version(before,expected);if(!before.get("state").equals("REQUESTED"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);String state=input.approve()?"APPROVED":"REJECTED";jdbc.update("UPDATE commerce.return_request SET state=?,reviewed_by=?,decision_reason=?,instructions=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",state,actor.party(),input.reason(),input.instructions(),stamp(),actor.party().toString(),id);touch(order,actor.party().toString());evidence(actor,id,correlation,AuditValues.Action.RETURN_REVIEW,state);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(Map.of("id",id)),id);});return current(actor,result.resource(),true);}
 public ReturnValues.Item receive(ActorAssertion.Actor actor,UUID id,long expected,ReturnValues.Receipt input,String key,UUID correlation){operations.require(actor);UUID order=owner(id);var result=execute(actor,"API-241",key,Map.of("id",id,"version",expected,"input",input),correlation,()->operations.require(actor),()->{operations.stabilize(actor);var o=order(order,true);var before=request(id);version(before,expected);if(!before.get("state").equals("APPROVED")||!delivered(o))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);UUID line=(UUID)before.get("order_line_id");if(available(order,line).signum()<0)throw OrderValues.rule();BigDecimal quantity=(BigDecimal)before.get("quantity");if(input.restock())restock(order,line,quantity,id,input,actor,correlation);jdbc.update("UPDATE commerce.return_request SET state='RECEIVED',received_by=?,received_at=?,receipt_reference=?,restock=?,inspection_reason=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",actor.party(),stamp(),input.receiptReference(),input.restock(),input.reason(),stamp(),actor.party().toString(),id);touch(order,actor.party().toString());evidence(actor,id,correlation,AuditValues.Action.RETURN_RECEIPT,"RECEIVED");return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(Map.of("id",id)),id);});return current(actor,result.resource(),true);}
 private void restock(UUID order,UUID line,BigDecimal quantity,UUID id,ReturnValues.Receipt input,ActorAssertion.Actor actor,UUID correlation){var balances=jdbc.queryForList("SELECT balance_id,-sum(CASE WHEN movement_type='DISPATCH' THEN delta_on_hand ELSE 0 END)-sum(CASE WHEN movement_type='RETURN' AND return_kind='PHYSICAL_RETURN' THEN delta_on_hand ELSE 0 END) AS remaining FROM commerce.inventory_movement WHERE order_id=? AND order_line_id=? GROUP BY balance_id ORDER BY balance_id",order,line);if(balances.size()>100)throw OrderValues.rule();BigDecimal left=quantity;for(var balance:balances){BigDecimal q=((BigDecimal)balance.get("remaining")).min(left);if(q.signum()<=0)continue;UUID target=(UUID)balance.get("balance_id");UUID command=UUID.nameUUIDFromBytes(("return:"+id+":"+target).getBytes(StandardCharsets.US_ASCII));stock.returned(order,List.of(new StockLedger.Line(line,target,PricingValues.decimal(q))),StockLedger.ReturnKind.PHYSICAL_RETURN,input.receiptReference(),input.reason(),command,actor.party().toString(),correlation);left=left.subtract(q);if(left.signum()==0)break;}if(left.signum()!=0)throw OrderValues.rule();}
 public ReturnValues.Item refund(ActorAssertion.Actor actor,UUID id,long expected,ReturnValues.Refund input,String key,UUID correlation){finance.require(actor,"FINANCE");paymentPolicy.require();UUID order=owner(id);var result=execute(actor,"API-242",key,Map.of("id",id,"version",expected,"input",input),correlation,()->finance.require(actor,"FINANCE"),()->{finance.stabilize(actor,"FINANCE");var o=order(order,true);var before=request(id);version(before,expected);if(!before.get("state").equals("RECEIVED")||before.get("refund_id")!=null)throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);var refund=refunds.request(order,((Number)o.get("version")).longValue(),new PaymentValues.RefundInput(input.amount(),input.reason(),List.of()),EventCodec.hash(EventCodec.JSON.valueToTree(Map.of("return",id))),actor.party());jdbc.update("UPDATE commerce.return_request SET refund_id=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",refund.id(),stamp(),actor.party().toString(),id);evidence(actor,id,correlation,AuditValues.Action.RETURN_REFUND_REQUEST,"REQUESTED");audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.REFUND_REQUEST,AuditValues.Resource.REFUND,refund.id(),correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("state",refund.state(),"version",refund.version(),"amount",refund.amount(),"currency",refund.currency()),null);var event=new LinkedHashMap<String,Object>();event.put("event_id",EventCodec.uuid7(clock.instant()));event.put("event_type","refund.requested.v1");event.put("schema_version",1);event.put("producer","commerce");event.put("occurred_at",clock.instant());event.put("aggregate_id",refund.id());event.put("aggregate_version",refund.version());event.put("organization_id",o.get("organization_id"));event.put("correlation_id",correlation);event.put("traceparent",null);event.put("payload",Map.of("refund_id",refund.id(),"order_id",order));commands.append(EventCodec.JSON.writeValueAsString(event),actor.party().toString());return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(Map.of("id",id)),id);});return current(actor,result.resource(),true);}
}
